  PRIMARY KEY (`appointment_id`, `visited_personnel_id`),
  CONSTRAINT `visit_appointment_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`appointment_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `visit_appointment_ibfk_2` FOREIGN KEY (`visited_personnel_id`) REFERENCES `personnel` (`personnel_id`) ON DELETE CASCADE ON UPDATE CASCADE
